/**
 *
 * Chip represents entities using icons, labels and images.
 *
 * [Live Demo](https://www.primereact.org/chip/)
 *
 * @module ChipRoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseChipExposes, UseChipProps, UseChipRemoveEvent, UseChipState } from '@primereact/types/headless/chip';
/**
 * Defines passthrough(pt) options type in Chip component.
 */
export type ChipRootPassThroughType<E> = PassThroughType<ChipRootInstance, E>;
/**
 * Defines passthrough(pt) options of Chip component.
 */
export interface ChipRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ChipRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the label's DOM element.
     */
    label?: ChipRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the remove's DOM element.
     */
    remove?: ChipRootPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
    /**
     * Used to pass attributes to the start's DOM element.
     */
    start?: ChipRootPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
    /**
     * Used to pass attributes to the end's DOM element.
     */
    end?: ChipRootPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Event fired when the chip's remove icon is clicked.
 * @extends UseChipRemoveEvent
 */
export interface ChipRootRemoveEvent extends UseChipRemoveEvent {
}
/**
 * Defines valid properties in Chip component.
 */
export interface ChipRootProps extends BaseComponentProps<ChipRootInstance, Omit<UseChipProps, 'onRemove'>, ChipRootPassThrough> {
    /**
     * Callback fired when the chip is removed.
     * @param event The event that triggered the remove.
     * @param event.originalEvent The original event that triggered the remove.
     * @returns void
     */
    onRemove?: (event: ChipRootRemoveEvent) => void;
}
/**
 * Defines valid state in Chip component.
 * @extends UseChipState
 */
export interface ChipRootState extends UseChipState {
}
/**
 * Defines the methods and properties exposed by Chip component.
 * @extends UseChipExposes
 */
export interface ChipRootExposes extends UseChipExposes {
}
/**
 * Instance of Chip component.
 */
export type ChipRootInstance = ComponentInstance<ChipRootProps, ChipRootState, ChipRootExposes>;
